import {TYPES,uid,plan,demo,validateProject,validChannels,isMotor,moduleType,csv} from './engine.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let project,view='overview',search='',filter='',editKind,editId,timer;
try{project=validateProject(JSON.parse(localStorage.getItem('orion-panel-v1')));}catch{project=demo();}
let result=plan(project);
const moduleLabels={relay:'Przekaźnikowy',dimmer:'Ściemniający',input:'Wejścia binarne'},icons={main:'☼',sconce:'◐',led:'⌁',blind:'▤',curtain:'▥',input:'◉'};
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function save(){try{validateProject(project);localStorage.setItem('orion-panel-v1',JSON.stringify(project));$('#save-state').textContent='● Zapisano lokalnie';}catch(e){$('#save-state').textContent='● Zapis lokalny niedostępny';toast('Pobierz kopię projektu: '+e.message);}result=plan(project);}
function download(name,data,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const options=(o,selected)=>Object.entries(o).map(([v,t])=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(t)}</option>`).join('');
function head(title,sub,actions=''){return `<div class="page-head"><div><p class="eyebrow">TWÓJ INTELIGENTNY DOM / PROJEKT ROZDZIELNI</p><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="head-actions">${actions}</div></div>`;}
const action=(name,text,cls='')=>`<button class="btn ${cls}" data-action="${esc(name)}">${text}</button>`;
function metrics(){const cap=project.modules.reduce((s,m)=>s+m.channels,0),busy=[...result.used.values()].flat().filter(Boolean).length;return `<div class="metrics"><div class="metric"><div class="metric-label">Obwody w projekcie <span>⌁</span></div><strong>${project.circuits.length}</strong><small>${new Set(project.circuits.map(c=>c.room)).size} pomieszczeń · KNX / Loxone</small></div><div class="metric"><div class="metric-label">Wykorzystane kanały <span>▤</span></div><strong>${busy}<em>/ ${cap}</em></strong><small>${cap-busy} kanałów w rezerwie</small></div><div class="metric"><div class="metric-label">Grupy zabezpieczeń <span>⊞</span></div><strong>${result.breakers.length}<em>MCB</em></strong><small>${project.settings.rcds} grup RCD · podział koncepcyjny</small></div><div class="metric"><div class="metric-label">Wymagają uwagi <span>◷</span></div><strong>${result.warnings.length.toString().padStart(2,'0')}</strong><small>${result.warnings.length?'Sprawdź przydział i separację':'Wszystkie obwody mają kanały'}</small></div></div>`;}
function mini(m){const busy=result.used.get(m.id).filter(Boolean).length;return `<div class="module-mini"><div class="mini-heading"><strong>${esc(m.name)}</strong><span class="pill">${m.system}</span></div><div class="mini-desc">${moduleLabels[m.type]} · ${m.channels} kanałów</div><div class="progress"><span style="width:${busy/m.channels*100}%"></span></div><div class="mini-bottom"><span>${busy} / ${m.channels} zajętych</span><span>${Math.round(busy/m.channels*100)}%</span></div></div>`;}
function device(m){return `<div class="device ${m.system==='LOXONE'?'lo':''}"><div class="device-name">${esc(m.name.split(' · ')[0])}</div><small>${m.system} · ${m.channels} CH</small><div class="device-stripe"></div><div class="device-channels">${result.used.get(m.id).map(x=>`<i class="${x?'on':''}"></i>`).join('')}</div></div>`;}
function warnings(){return result.warnings.length?`<div class="notice">${result.warnings.map(w=>`<div>△ ${esc(w.text)}</div>`).join('')}</div>`:'';}
function table(rows,editable=false){if(!rows.length)return '<div class="empty"><strong>Tu zaczyna się Twój projekt</strong>Dodaj obwód ręcznie lub rozpoznaj symbole w pliku PDF.</div>';return `<div class="table-wrap"><table><thead><tr><th>Obwód / pomieszczenie</th><th>Typ</th><th>Moduł · kanał</th><th>MCB / RCD</th>${editable?'<th>Moc</th><th></th>':''}</tr></thead><tbody>${rows.map(c=>{const m=project.modules.find(m=>m.id===c.moduleId);return `<tr><td><span class="type-icon">${icons[c.type]}</span><span class="circuit-name">${esc(c.name)}</span><br><span class="muted" style="margin-left:36px">${esc(c.room)}</span></td><td><span class="tag ${c.type==='led'?'orange':isMotor(c)?'blue':''}">${TYPES[c.type]}</span></td><td class="mono">${m?esc(m.name.split(' · ')[0])+' · '+c.channels.map(x=>'A'+x).join(' / '):'<span class="tag red">Brak kanału</span>'}<br><span class="muted">${c.system}</span></td><td class="mono">${c.breaker||'—'} ${c.rcd?' / RCD '+c.rcd:''}</td>${editable?`<td>${c.watts} W</td><td><button class="icon-btn" data-edit-c="${esc(c.id)}" aria-label="Edytuj ${esc(c.name)}">✎</button><button class="icon-btn danger" data-del-c="${esc(c.id)}" aria-label="Usuń ${esc(c.name)}">×</button></td>`:''}</tr>`;}).join('')}</tbody></table></div>`;}
function overview(){return head('Przegląd projektu','Od planu domu do uporządkowanej rozdzielni.',`<span class="status">● Projekt koncepcyjny</span>${action('project-settings','⚙ Ustawienia')}`)+`<div class="hero"><div><p class="eyebrow">DOBRZE ZAPLANOWANE. DOBRZE POŁĄCZONE.</p><h2>${esc(project.name)}</h2><p>Każdy obwód na swoim miejscu. Zaplanuj moduły, rozdziel zabezpieczenia<br>i stwórz przejrzystą dokumentację Twojego smart home.</p></div><div class="head-actions">${action('pdf','↥ Importuj PDF')}${action('add-circuit','＋ Dodaj obwód','dark')}</div></div>`+metrics()+`<div class="grid-main"><div><section class="card"><div class="card-head"><h2>Twoja rozdzielnia</h2><small>WIDOK POGLĄDOWY · DIN</small></div><div class="panel-visual">${project.modules.length?Array.from({length:Math.ceil(project.modules.length/4)},(_,i)=>`<div class="din-row"><span class="row-num">RZĄD ${String(i+1).padStart(2,'0')}</span>${project.modules.slice(i*4,i*4+4).map(device).join('')}</div>`).join(''):'<div class="empty">Dodaj pierwszy moduł.</div>'}<div class="din-legend"><span><i class="legend-dot"></i>Kanał zajęty</span><span><i class="legend-dot free"></i>Rezerwa</span><span style="margin-left:auto">${project.modules.length} moduły</span></div></div><div class="info-strip"><span>Widok logiczny — bez odwzorowania szerokości aparatów</span><button class="text-btn" data-action="modules">Zarządzaj modułami ↗</button></div></section><section class="card"><div class="card-head"><h2>Lista obwodów</h2><button class="text-btn" data-action="circuits">Wszystkie obwody ↗</button></div>${table(result.assignments.slice(0,5))}<div class="table-foot"><span>${Math.min(5,project.circuits.length)} z ${project.circuits.length} obwodów</span><span>Automatyczny przydział kanałów ✓</span></div></section></div><div><section class="card"><div class="card-head"><h2>Moduły w projekcie</h2><button class="text-btn" data-action="add-module">＋ Dodaj</button></div>${project.modules.slice(0,5).map(mini).join('')||'<div class="empty">Brak modułów</div>'}</section><div class="tip"><strong>✧ Rozdziel światło, zachowaj komfort</strong>Główne oświetlenie, kinkiety i LED w jednym pomieszczeniu trafiają do różnych grup RCD, gdy pozwala na to ich liczba.<br><button class="text-btn" data-action="protection">Zobacz podział zabezpieczeń →</button></div></div></div>`;}
function circuits(){return head('Obwody','Zdefiniuj odbiorniki. Kanały i grupy zabezpieczeń przeliczą się automatycznie.',action('csv','↓ Eksport CSV')+action('add-circuit','＋ Dodaj obwód','primary'))+warnings()+`<section class="card"><div class="toolbar"><input id="search" aria-label="Szukaj obwodu" placeholder="Szukaj pomieszczenia lub obwodu…" value="${esc(search)}"><select id="type-filter" aria-label="Filtr rodzaju"><option value="">Wszystkie typy</option>${options(TYPES,filter)}</select></div><div id="circuit-table">${filteredTable()}</div></section>`;}
function filteredTable(){const q=search.toLocaleLowerCase('pl');return table(result.assignments.filter(c=>(!filter||c.type===filter)&&(c.name+' '+c.room).toLocaleLowerCase('pl').includes(q)),true);}
function modules(){return head('Moduły i kanały','Konfiguruj pojemność modułów KNX i Loxone. Rolety zajmują sąsiednie pary kanałów.',action('add-module','＋ Dodaj moduł','primary'))+warnings()+`<div class="modules-grid">${project.modules.map(m=>`<section class="card module-full"><div class="mini-heading"><strong>${esc(m.name)}</strong><span class="pill">${m.system}</span></div><p class="mini-desc">${moduleLabels[m.type]} · ${m.channels} kanałów${m.blindCapable?' · pary roletowe':''}</p><div class="channel-grid">${result.used.get(m.id).map((id,i)=>`<div class="channel ${id?'occupied':''}" title="${esc(id?project.circuits.find(c=>c.id===id)?.room+' · '+project.circuits.find(c=>c.id===id)?.name:'Wolny kanał')}">A${i+1}</div>`).join('')}</div><div class="head-actions">${action('edit-module:'+m.id,'✎ Edytuj')}${action('del-module:'+m.id,'Usuń')}</div></section>`).join('')}</div><div class="notice good">Moduły uniwersalne: przekaźnikowe 2–24 (parzyste, domyślnie 24), binarne 2–24 (parzyste, domyślnie 4), ściemniające domyślnie 4. Profil Loxone Relay Extension: 14 wyjść. Kanały różnych systemów nie są mieszane.</div><div class="source-links"><a href="https://katalog.gira.de/en-GB/datenblatt/4010337060987" target="_blank" rel="noreferrer">Gira: 24 wyjścia / 12 rolet ↗</a><a href="https://pim.loxone.com/datasheet/100038-relay-extension" target="_blank" rel="noreferrer">Loxone Relay Extension ↗</a></div>`;}
function protection(){return head('Zabezpieczenia','Kolejność przydziału: główne oświetlenie → kinkiety → LED → napędy.',action('csv','↓ Eksport CSV'))+`<section class="card"><div class="settings"><label>Liczba grup RCD<input id="rcd-count" type="number" min="2" max="12" value="${project.settings.rcds}"></label><label>Obwodów na MCB (maks.)<input id="breaker-max" type="number" min="1" max="20" value="${project.settings.maxPerBreaker}"></label>${action('save-settings','Przelicz podział','primary')}</div></section>`+warnings()+`<div class="notice">To propozycja grupowania, bez doboru prądów znamionowych, charakterystyk, typów RCD ani bilansu faz. Nie wolno łączyć przewodów N między grupami RCD. Zasilania LED i wspólne zaciski modułów wymagają sprawdzenia z dokumentacją aparatów.</div>${Array.from({length:project.settings.rcds},(_,i)=>`<h2 class="rcd-title">RCD ${i+1} <span class="muted small">/ ${result.breakers.filter(b=>b.rcd===i+1).length} grup MCB</span></h2><div class="breaker-grid">${result.breakers.filter(b=>b.rcd===i+1).map(b=>`<section class="card breaker-card"><div class="mini-heading"><strong class="mono">${b.id}</strong><span class="tag">${TYPES[b.type]}</span></div><p class="small">${b.system} · ${b.ids.length} obwody · ${b.watts} W zadeklarowane</p><ul>${b.ids.map(id=>{const c=project.circuits.find(c=>c.id===id);return `<li>${esc(c.room)} · ${esc(c.name)}</li>`;}).join('')}</ul></section>`).join('')||'<p class="small">Brak przypisanych obwodów.</p>'}</div>`).join('')}`;}
function terminalInfo(c){return c.type==='input'?{model:'2003-76xx · dobór sygnałowy',qty:1,wire:'Sygnał / wspólny — do weryfikacji'}:isMotor(c)?{model:'2003-76xx · zestaw napędu',qty:2,wire:'L↑ / L↓ / N / PE — dobór wariantów'}:c.type==='led'?{model:'2003-76xx · dobór zasilania LED',qty:1,wire:'Strona AC lub DC — ustal z projektantem'}:{model:'2003-7646',qty:1,wire:'L / N / PE'};}
function terminals(){return head('Listwa zaciskowa','Logiczny plan zacisków WAGO TOPJOB® S serii 2003-76xx.',action('terminal-csv','↓ Zestawienie CSV'))+`<div class="notice">2003-7646 to złączka N/L/PE. Dla napędów, sygnałów binarnych i obwodów LED plan oznacza wymagany dobór wariantów oraz mostków. Liczby zestawów są szacunkowe; nie stanowią gotowego BOM do zamówienia. Szyny N zachowaj oddzielnie dla każdej grupy RCD.</div><section class="card"><div class="card-head"><h2>Plan oznaczeń zacisków</h2><small>${result.assignments.length} punktów przyłączeniowych</small></div><div class="terminal-rack">${result.assignments.map(c=>`<div class="terminal" title="${esc(c.room+' · '+c.name)}"><span>${c.terminal}</span><i></i><i></i><i></i><b>${esc(c.room)} · ${esc(c.name)}</b><span>${c.rcd?'R'+c.rcd:'SIG'}</span></div>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>Zacisk</th><th>Obwód</th><th>Wariant / zestaw</th><th>Szt. szac.</th><th>Potencjały</th><th>RCD</th></tr></thead><tbody>${result.assignments.map(c=>{const t=terminalInfo(c);return `<tr><td class="mono">${c.terminal}</td><td>${esc(c.room)} · ${esc(c.name)}</td><td>${t.model}</td><td>${t.qty}</td><td>${t.wire}</td><td>${c.rcd||'—'}</td></tr>`;}).join('')}</tbody></table></div></section><div class="source-links"><a href="https://www.wago.com/gb/rail-mount-terminal-blocks/multilevel-installation-terminal-block/p/2003-7646" target="_blank" rel="noreferrer">WAGO 2003-7646 · karta produktu ↗</a></div>`;}
function render(){result=plan(project);$('#project-crumb').textContent=project.name;$('#nav-count').textContent=project.circuits.length;document.querySelectorAll('#nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');b.title=b.textContent.trim();});$('#main').innerHTML=({overview,circuits,modules,protection,terminals,pdf:pdfView})[view]();if(view==='pdf')mountPdf();}
function navigate(v){view=v;render();window.scrollTo(0,0);}
function circuitEditor(id){editKind='circuit';editId=id;const c=project.circuits.find(c=>c.id===id)||{name:'',room:'',type:'main',system:'KNX',control:'relay',watts:60,motor:'directional'};$('#dialog-title').textContent=id?'Edytuj obwód':'Nowy obwód';$('#form-fields').innerHTML=`<div class="form-grid"><label class="full">Nazwa obwodu<input name="name" value="${esc(c.name)}" required maxlength="100" placeholder="np. Lampa sufitowa"></label><label>Pomieszczenie<input name="room" value="${esc(c.room)}" required maxlength="80" list="rooms"><datalist id="rooms">${[...new Set(project.circuits.map(c=>c.room))].map(r=>`<option value="${esc(r)}">`).join('')}</datalist></label><label>Typ<select name="type">${options(TYPES,c.type)}</select></label><label>System<select name="system">${options({KNX:'KNX',LOXONE:'LOXONE'},c.system)}</select></label><label>Sterowanie<select name="control">${options({relay:'Przekaźnik / wejście',dim:'Ściemnianie'},c.control)}</select></label><label>Moc deklarowana (W)<input name="watts" type="number" min="0" max="100000" step="0.1" value="${c.watts}" required></label><label>Napęd karnisza<select name="motor">${options({directional:'Dwukierunkowy (2 kanały)',impulse:'Impulsowy (1 kanał)'},c.motor)}</select></label><p class="small full">Rolety i karnisze dwukierunkowe wymagają par A1/A2, A3/A4… oraz blokady kierunków w konfiguracji urządzenia. Taśmy LED mogą korzystać z przekaźnika lub zgodnego sterownika ściemniającego.</p></div>`;showEditor();}
function moduleEditor(id){editKind='module';editId=id;const m=project.modules.find(m=>m.id===id)||{name:'',type:'relay',system:'KNX',channels:24,blindCapable:true};$('#dialog-title').textContent=id?'Edytuj moduł':'Nowy moduł';$('#form-fields').innerHTML=`<div class="form-grid"><label class="full">Profil<select id="module-profile"><option value="custom">Moduł uniwersalny / własny</option><option value="gira">Gira · przełączający 24 / roletowy 12</option><option value="loxone">Loxone Relay Extension · 14 wyjść</option></select></label><label class="full">Nazwa / oznaczenie<input name="name" value="${esc(m.name)}" required maxlength="100" placeholder="np. A2 · Aktor przełączający"></label><label>Typ<select name="type" id="module-type">${options(moduleLabels,m.type)}</select></label><label>System<select name="system">${options({KNX:'KNX',LOXONE:'LOXONE'},m.system)}</select></label><label class="full">Liczba kanałów<input name="channels" type="number" min="${m.type==='dimmer'?1:2}" max="24" step="${m.type==='dimmer'?1:2}" value="${m.channels}" required></label><label class="checkbox full"><input name="blindCapable" type="checkbox" ${m.blindCapable?'checked':''}> Obsługa napędów: pary kanałów z blokadą kierunków</label><p class="small full">Zaznacz obsługę napędów wyłącznie dla kompatybilnego aktora i konfiguracji. Liczba kanałów nie oznacza identycznych parametrów elektrycznych urządzeń.</p></div>`;showEditor();}
function showEditor(){$('#form-error').textContent='';$('#editor').showModal();}
function settingsEditor(){editKind='settings';$('#dialog-title').textContent='Ustawienia projektu';$('#form-fields').innerHTML=`<label>Nazwa projektu<input name="name" value="${esc(project.name)}" required maxlength="150"></label><div class="head-actions" style="margin-top:20px">${action('new-project','Nowy pusty projekt')}${action('demo','Wczytaj przykład')}</div><p class="small">Przed zastąpieniem projektu pobierz jego kopię przyciskiem „Zapisz projekt”.</p>`;showEditor();}
$('#editor-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),v=Object.fromEntries(f);try{if(editKind==='settings')project.name=v.name.trim();else if(editKind==='module'){const m={id:editId||uid(),name:v.name.trim(),type:v.type,system:v.system,channels:Number(v.channels),blindCapable:v.type==='relay'&&f.has('blindCapable')};if(!validChannels(m.type,m.channels))throw Error('Podaj parzystą liczbę 2–24; dla ściemniacza od 1 do 24.');if(!m.name)throw Error('Podaj nazwę.');const ix=project.modules.findIndex(x=>x.id===editId);if(ix>=0)project.modules[ix]=m;else project.modules.push(m);}else{const c={...project.circuits.find(x=>x.id===editId),id:editId||uid(),name:v.name.trim(),room:v.room.trim(),type:v.type,system:v.system,control:v.control,watts:Number(v.watts),motor:v.motor};if(!c.name||!c.room)throw Error('Podaj nazwę i pomieszczenie.');if((isMotor(c)||c.type==='input')&&c.control==='dim')throw Error('Napędy i wejścia binarne nie mogą używać modułu ściemniającego.');const ix=project.circuits.findIndex(x=>x.id===editId);if(ix>=0)project.circuits[ix]=c;else project.circuits.push(c);}save();$('#editor').close();render();toast('Zapisano. Przydział został przeliczony.');}catch(err){$('#form-error').textContent=err.message;}});
$('#close-dialog').onclick=$('#cancel-dialog').onclick=()=>$('#editor').close();
function exportCsv(term=false){const rows=term?[['Zacisk','Pomieszczenie','Obwód','Wariant','Szt. szac.','Potencjały','RCD'],...result.assignments.map(c=>{const t=terminalInfo(c);return[c.terminal,c.room,c.name,t.model,t.qty,t.wire,c.rcd];})]:[['Pomieszczenie','Obwód','Typ','System','Moduł','Kanały','MCB','RCD','Zacisk','Moc W'],...result.assignments.map(c=>[c.room,c.name,TYPES[c.type],c.system,project.modules.find(m=>m.id===c.moduleId)?.name||'BRAK',c.channels.join('/'),c.breaker,c.rcd,c.terminal,c.watts])];download(term?'orion-zaciski.csv':'orion-obwody.csv',csv(rows),'text/csv;charset=utf-8');}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)return navigate(b.dataset.view);if(b.dataset.editC)return circuitEditor(b.dataset.editC);if(b.dataset.delC){if(!confirm('Usunąć ten obwód?'))return;project.circuits=project.circuits.filter(c=>c.id!==b.dataset.delC);save();render();return;}const a=b.dataset.action;if(!a)return;if(['overview','circuits','modules','protection','terminals','pdf'].includes(a))return navigate(a);if(a==='add-circuit')circuitEditor();if(a==='add-module')moduleEditor();if(a.startsWith('edit-module:'))moduleEditor(a.split(':')[1]);if(a.startsWith('del-module:')){if(confirm('Usunąć moduł? Obwody pozostaną w projekcie.')){project.modules=project.modules.filter(m=>m.id!==a.split(':')[1]);save();render();}}if(a==='project-settings')settingsEditor();if(a==='csv')exportCsv();if(a==='terminal-csv')exportCsv(true);if(a==='save-settings'){const r=Number($('#rcd-count').value),n=Number($('#breaker-max').value);if(!Number.isInteger(r)||r<2||r>12||!Number.isInteger(n)||n<1||n>20)return toast('RCD: 2–12; obwody na MCB: 1–20.');project.settings={rcds:r,maxPerBreaker:n};save();render();toast('Przeliczono grupy zabezpieczeń.');}if(['new-project','demo'].includes(a)){if(!confirm('Zastąpić bieżący projekt? Pobierz kopię przed kontynuacją.'))return;project=a==='demo'?demo():{version:1,name:'Nowy projekt',circuits:[],modules:[],settings:{rcds:3,maxPerBreaker:4}};save();$('#editor').close();navigate('overview');}if(a==='upload-pdf')$('#pdf-file').click();if(a==='pdf-search')await findSymbols();if(a==='pdf-accept')acceptSymbols();if(a==='pdf-text')await extractLabels();if(a==='pdf-clear'){pdfState.selection=null;pdfState.matches=[];drawOverlay();showMatches();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('#circuit-table').innerHTML=filteredTable();}});
document.addEventListener('change',e=>{if(e.target.id==='type-filter'){filter=e.target.value;$('#circuit-table').innerHTML=filteredTable();}if(e.target.id==='module-type'){const t=e.target.value,i=$('#editor-form [name=channels]');i.value=t==='relay'?24:4;i.min=t==='dimmer'?1:2;i.step=t==='dimmer'?1:2;$('#editor-form [name=blindCapable]').checked=t==='relay';}if(e.target.id==='module-profile'){const p=e.target.value;if(p==='custom')return;$('#editor-form [name=name]').value=p==='gira'?'Gira · 24 / 12':'Loxone Relay Extension';$('#module-type').value='relay';$('#editor-form [name=system]').value=p==='gira'?'KNX':'LOXONE';$('#editor-form [name=channels]').value=p==='gira'?24:14;$('#editor-form [name=blindCapable]').checked=true;}if(e.target.id==='pdf-page'){pdfState.page=Number(e.target.value);pdfState.selection=null;pdfState.matches=[];renderPdfPage();}});
$('#save-project').onclick=()=>download('orion-panel.json',JSON.stringify(project,null,2),'application/json');$('#load-project').onclick=()=>$('#json-file').click();$('#json-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10e6)throw Error('Plik przekracza 10 MB.');const p=validateProject(JSON.parse(await f.text()));if(!confirm('Zastąpić projekt danymi z pliku?'))return;project=p;save();render();toast('Projekt został otwarty.');}catch(err){toast('Nie można otworzyć projektu: '+err.message);}finally{e.target.value='';}};
const pdfState={doc:null,name:'',page:1,selection:null,matches:[],labels:[],canvas:null,renderTask:null,busy:false,source:uid()};
function pdfView(){return head('Import projektu PDF','Odczytaj symbole z rysunku i zamień je na edytowalną listę obwodów.',action('upload-pdf','↥ Wybierz plik PDF','primary'))+`<div class="pdf-grid"><section class="card"><div class="pdf-tools"><strong id="pdf-name" class="small">${esc(pdfState.name||'PDF przetwarzany lokalnie · maks. 40 MB')}</strong><label class="small" style="margin:0">Strona <select id="pdf-page" ${pdfState.doc?'':'disabled'}>${pdfState.doc?Array.from({length:pdfState.doc.numPages},(_,i)=>`<option value="${i+1}" ${pdfState.page===i+1?'selected':''}>${i+1} / ${pdfState.doc.numPages}</option>`).join(''):'<option>—</option>'}</select></label>${action('pdf-clear','Wyczyść zaznaczenie')}</div><div class="pdf-stage" id="pdf-stage">${pdfState.doc?'<div class="canvas-wrap"><canvas id="pdf-canvas"></canvas><canvas id="pdf-overlay" aria-label="Zaznacz wzorcowy symbol na planie"></canvas></div>':'<div class="empty"><strong>Twój rzut. Twoje symbole.</strong>Wczytaj PDF, zaznacz jeden symbol i wyszukaj jego powtórzenia.<br>Plik pozostaje w pamięci tej przeglądarki.<br><br><button class="btn" data-action="upload-pdf">＋ Wybierz projekt PDF</button></div>'}</div><div class="info-strip"><span id="pdf-status">${pdfState.doc?'Zaznacz prostokąt wokół jednego symbolu.':'Obsługuje pliki wektorowe i skany.'}</span></div></section><div><section class="card"><div class="card-head"><h2>Od symbolu do obwodu</h2><span class="pill">LOKALNIE</span></div><div class="pdf-instructions"><ol><li>Zaznacz myszą sam symbol z niewielkim białym marginesem.</li><li>Wyszukaj podobne symbole na bieżącej stronie. Dopasowanie zakłada tę samą skalę i obrót.</li><li>Sprawdź wyniki. Nadaj typ i pomieszczenie, potem dodaj obwody.</li></ol><label>Pomieszczenie dla partii<input id="pdf-room" value="Nieprzypisane" maxlength="80"></label><label>Rodzaj obwodu<select id="pdf-kind">${options(TYPES,'main')}</select></label><label>System<select id="pdf-system">${options({KNX:'KNX',LOXONE:'LOXONE'},'KNX')}</select></label><label>Próg podobieństwa<select id="pdf-threshold"><option value="0.92">Wysoki · 92%</option><option value="0.88" selected>Standardowy · 88%</option><option value="0.82">Niższy · 82%</option></select></label>${action('pdf-search','⌕ Wyszukaj symbole','primary')}<p class="small">Każdy symbol jest kandydatem na obwód. Połącz punkty tego samego obwodu przez edycję listy. Brak automatycznej interpretacji dowolnej legendy i OCR.</p>${action('pdf-text','Odczytaj etykiety tekstowe')}</div><div id="pdf-labels" class="pdf-instructions" style="padding-top:0"></div></section><section class="card"><div class="card-head"><h2>Wyniki do sprawdzenia</h2><small id="match-count">0</small></div><div class="result-list" id="pdf-matches"></div><div class="actions-bottom">${action('pdf-accept','＋ Dodaj zaznaczone','primary')}</div></section></div></div>`;}
async function mountPdf(){if(pdfState.doc)await renderPdfPage();showMatches();}
$('#pdf-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>40e6)throw Error('Maksymalny rozmiar PDF to 40 MB.');toast('Otwieranie PDF…');const lib=await import('./vendor/pdf.mjs');lib.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;const doc=await lib.getDocument({data:new Uint8Array(await f.arrayBuffer()),isEvalSupported:false,wasmUrl:new URL('./vendor/wasm/',import.meta.url).href,cMapUrl:new URL('./vendor/cmaps/',import.meta.url).href,cMapPacked:true,standardFontDataUrl:new URL('./vendor/standard_fonts/',import.meta.url).href}).promise;if(pdfState.doc)await pdfState.doc.destroy();pdfState.doc=doc;pdfState.name=f.name;pdfState.page=1;pdfState.source=uid();pdfState.selection=null;pdfState.matches=[];pdfState.labels=[];navigate('pdf');}catch(err){toast('Nie udało się odczytać PDF: '+err.message);}finally{e.target.value='';}};
async function renderPdfPage(){if(!pdfState.doc||!$('#pdf-canvas'))return;try{if(pdfState.renderTask){pdfState.renderTask.cancel();await pdfState.renderTask.promise.catch(()=>{});}const page=await pdfState.doc.getPage(pdfState.page);const base=page.getViewport({scale:1}),scale=Math.min(2,1400/base.width,1800/base.height),vp=page.getViewport({scale});const canvas=$('#pdf-canvas'),overlay=$('#pdf-overlay');if(!canvas)return;canvas.width=Math.ceil(vp.width);canvas.height=Math.ceil(vp.height);overlay.width=canvas.width;overlay.height=canvas.height;pdfState.canvas=canvas;pdfState.renderTask=page.render({canvasContext:canvas.getContext('2d',{willReadFrequently:true}),viewport:vp});await pdfState.renderTask.promise;drawOverlay();bindSelection();}catch(err){if(err.name!=='RenderingCancelledException')toast('Błąd renderowania: '+err.message);}}
function bindSelection(){const o=$('#pdf-overlay');let start=null;const point=e=>{const r=o.getBoundingClientRect();return{x:Math.max(0,Math.min(o.width-1,Math.round((e.clientX-r.left)*o.width/r.width))),y:Math.max(0,Math.min(o.height-1,Math.round((e.clientY-r.top)*o.height/r.height)))};};o.onpointerdown=e=>{if(pdfState.busy)return;start=point(e);o.setPointerCapture(e.pointerId);pdfState.matches=[];};o.onpointermove=e=>{if(!start)return;const p=point(e);pdfState.selection={x:Math.min(start.x,p.x),y:Math.min(start.y,p.y),w:Math.abs(p.x-start.x),h:Math.abs(p.y-start.y)};drawOverlay();};o.onpointerup=()=>{start=null;showMatches();const r=pdfState.selection;if(r)$('#pdf-status').textContent=`Wzorzec ${r.w} × ${r.h} px. Kliknij „Wyszukaj symbole”.`;};o.onpointercancel=()=>{start=null;};}
function drawOverlay(){const o=$('#pdf-overlay');if(!o)return;const ctx=o.getContext('2d');ctx.clearRect(0,0,o.width,o.height);pdfState.matches.forEach((m,i)=>{ctx.strokeStyle=m.added?'#83918b':'#168c75';ctx.lineWidth=2;ctx.strokeRect(m.x,m.y,m.w,m.h);ctx.fillStyle='#168c75';ctx.fillRect(m.x,m.y-15,25,15);ctx.fillStyle='white';ctx.font='10px sans-serif';ctx.fillText(i+1,m.x+4,m.y-4);});const r=pdfState.selection;if(r){ctx.strokeStyle='#df8b4f';ctx.lineWidth=2;ctx.setLineDash([5,3]);ctx.strokeRect(r.x,r.y,r.w,r.h);ctx.setLineDash([]);}}
function showMatches(){if(!$('#pdf-matches'))return;$('#match-count').textContent=pdfState.matches.length;$('#pdf-matches').innerHTML=pdfState.matches.map((m,i)=>`<label class="result-item"><input type="checkbox" data-match="${i}" ${m.added?'disabled':'checked'}> Symbol ${i+1} <span class="muted">${Math.round(m.score*100)}%${m.added?' · dodany':''}</span></label>`).join('')||'<p class="small">Brak wyników. Zaznacz symbol na planie.</p>';}
async function findSymbols(){const r=pdfState.selection;if(!pdfState.canvas||!r||r.w<8||r.h<8)return toast('Zaznacz symbol o wielkości co najmniej 8 × 8 px.');if(r.w>240||r.h>240)return toast('Zaznacz pojedynczy symbol (do 240 × 240 px).');if(pdfState.busy)return;pdfState.busy=true;const button=$('[data-action="pdf-search"]');button.disabled=true;try{const {matchTemplate}=await import('./matcher.js');const c=pdfState.canvas,rgba=c.getContext('2d').getImageData(0,0,c.width,c.height).data,gray=new Uint8Array(c.width*c.height);for(let i=0;i<gray.length;i++)gray[i]=(rgba[i*4]+rgba[i*4+1]+rgba[i*4+2])/3;const found=await matchTemplate(gray,c.width,c.height,r,Number($('#pdf-threshold').value),n=>{if($('#pdf-status'))$('#pdf-status').textContent=`Wyszukiwanie… ${Math.round(n*100)}%`;});pdfState.matches=found.map(m=>({...m,added:false}));drawOverlay();showMatches();if($('#pdf-status'))$('#pdf-status').textContent=`Znaleziono ${found.length} kandydatów. Sprawdź każdy wynik.${found.length===300?' Osiągnięto limit 300.':''}`;}catch(err){toast(err.message);}finally{pdfState.busy=false;if(button.isConnected)button.disabled=false;}}
function acceptSymbols(){const checked=[...document.querySelectorAll('[data-match]:checked:not(:disabled)')].map(i=>Number(i.dataset.match));if(!checked.length)return toast('Zaznacz wyniki do dodania.');const room=$('#pdf-room').value.trim()||'Nieprzypisane',type=$('#pdf-kind').value,system=$('#pdf-system').value;let count=0;for(const i of checked){const m=pdfState.matches[i],key=`${pdfState.source}:${pdfState.page}:${Math.round(m.x/8)}:${Math.round(m.y/8)}`;if(project.circuits.some(c=>c.source?.key===key)){m.added=true;continue;}project.circuits.push({id:uid(),name:`${TYPES[type]} ${i+1}`,room,type,system,watts:type==='input'?0:60,control:type==='led'?'dim':'relay',motor:'directional',source:{key,file:pdfState.name,page:pdfState.page,x:m.x,y:m.y}});m.added=true;count++;}save();$('#nav-count').textContent=project.circuits.length;showMatches();drawOverlay();toast(`Dodano ${count} obwodów. Sprawdź pomieszczenia, moc i typ sterowania w liście obwodów.`);}
async function extractLabels(){if(!pdfState.doc)return toast('Wczytaj PDF.');try{const p=await pdfState.doc.getPage(pdfState.page),t=await p.getTextContent();const labels=t.items.map(i=>i.str.trim()).filter(Boolean);$('#pdf-labels').innerHTML=labels.length?`<strong>Tekst na stronie (${labels.length}):</strong><p>${esc(labels.slice(0,100).join(' · '))}</p>`:'Brak warstwy tekstowej. Użyj zaznaczania symboli na skanie.';}catch(err){toast(err.message);}}
save();render();


